{"output": "def transform(grid):
    h,w=len(grid),len(grid[0])
    centers=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,3)]
    out=[row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]==3: continue
            sources=[]
            for sr,sc,v in centers:
                if sr==r: sources.append((abs(sc-c),0,v))
                elif sc==c: sources.append((abs(sr-r),1,v))
            if sources:
                out[r][c]=min(sources)[2]
    return out", "exit_code": 0, "error": null}
